package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true // Allow all origins for WebSocket upgrade
	},
}

const uploadDir = "/var/uploads/realtime"
const maxFileSize = 50 * 1024 * 1024 // 50MB

func generateFilename(originalName string) string {
	bytes := make([]byte, 16)
	rand.Read(bytes)
	ext := filepath.Ext(originalName)
	return hex.EncodeToString(bytes) + ext
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	// Authentication via token in first message
	_, tokenMsg, err := conn.ReadMessage()
	if err != nil {
		return
	}
	token := string(tokenMsg)
	if !validateSessionToken(token) {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"unauthorized"}`))
		return
	}

	for {
		msgType, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}

		if msgType == websocket.TextMessage {
			// Handle text commands
			handleCommand(conn, string(msg))
		} else if msgType == websocket.BinaryMessage {
			// Binary messages are file uploads
			// Protocol: first 256 bytes = filename (null-padded), rest = content
			if len(msg) < 257 {
				conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid upload format"}`))
				continue
			}

			filenameRaw := strings.TrimRight(string(msg[:256]), "\x00")
			fileContent := msg[256:]

			if len(fileContent) > maxFileSize {
				conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"file too large"}`))
				continue
			}

			// Generate safe filename but preserve extension for content-type serving
			safeFilename := generateFilename(filenameRaw)
			destPath := filepath.Join(uploadDir, safeFilename)

			// No content-type validation - accepts any file type
			// No magic byte verification
			err = ioutil.WriteFile(destPath, fileContent, 0644)
			if err != nil {
				conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"error":"%s"}`, err.Error())))
				continue
			}

			response := fmt.Sprintf(`{"status":"uploaded","filename":"%s","size":%d,"url":"/files/%s"}`,
				safeFilename, len(fileContent), safeFilename)
			conn.WriteMessage(websocket.TextMessage, []byte(response))
		}
	}
}

func validateSessionToken(token string) bool {
	// Validates against session store - simplified
	return len(token) == 64 && token != ""
}

func handleCommand(conn *websocket.Conn, cmd string) {
	parts := strings.SplitN(cmd, " ", 2)
	switch parts[0] {
	case "LIST":
		files, _ := ioutil.ReadDir(uploadDir)
		var names []string
		for _, f := range files {
			names = append(names, f.Name())
		}
		conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"files":[%s]}`, strings.Join(names, ","))))
	case "DELETE":
		if len(parts) > 1 {
			target := filepath.Base(parts[1])
			os.Remove(filepath.Join(uploadDir, target))
			conn.WriteMessage(websocket.TextMessage, []byte(`{"status":"deleted"}`))
		}
	}
}

func main() {
	os.MkdirAll(uploadDir, 0755)
	http.HandleFunc("/ws", handleWebSocket)
	http.Handle("/files/", http.StripPrefix("/files/", http.FileServer(http.Dir(uploadDir))))
	log.Println("WebSocket file service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
